function impact_ice(ctx,dest,p){const t=ctx.currentTime;const mappedImpactGain=Number.isFinite(p.impactGain)?clamp(p.impactGain,0.2,2.2):1.0;const mappedBrittleness=Number.isFinite(p.brittleness)?clamp(p.brittleness,0.55,2.0):1.0;const vol=(p.volume??0.5)*mappedImpactGain;const pitch=p.pitch??1.0;const spd=Math.min((p.speed??3)/6,2.0);const temp=Math.min((p.temperature??200)/500,1.0);const crackDur=0.035+spd*0.02;const crackIntensity=(0.6+(1.0-temp)*0.2)*(0.8+mappedBrittleness*0.35);const brittleQ=(1.0+(1.0-temp)*2.5)*mappedBrittleness;const chirp=ctx.createOscillator();chirp.type='triangle';chirp.frequency.setValueAtTime((4800+spd*1200)*pitch,t);chirp.frequency.exponentialRampToValueAtTime((1500+spd*500)*pitch,t+0.012);const chirpEnv=ctx.createGain();chirpEnv.gain.setValueAtTime(vol*0.16*(1.0-temp*0.6),t);chirpEnv.gain.exponentialRampToValueAtTime(0.001,t+0.012);chirp.connect(chirpEnv).connect(dest);chirp.start(t);chirp.stop(t+0.02);const n=noiseShot(ctx,crackDur+0.05);const hp=ctx.createBiquadFilter();hp.type='highpass';hp.frequency.value=2000*pitch;hp.Q.value=brittleQ;const nEnv=ctx.createGain();nEnv.gain.setValueAtTime(vol*crackIntensity,t);nEnv.gain.exponentialRampToValueAtTime(0.001,t+crackDur);n.connect(hp).connect(nEnv).connect(dest);const pingDur=0.18+spd*0.08;const baseFreq=2400*pitch+randRange(0,400);const osc1=ctx.createOscillator();osc1.type='sine';osc1.frequency.value=baseFreq;const oEnv1=ctx.createGain();oEnv1.gain.setValueAtTime(vol*0.3,t);oEnv1.gain.exponentialRampToValueAtTime(0.001,t+pingDur);osc1.connect(oEnv1).connect(dest);osc1.start(t);osc1.stop(t+pingDur+0.05);const osc2=ctx.createOscillator();osc2.type='sine';osc2.frequency.value=baseFreq*1.618;const oEnv2=ctx.createGain();oEnv2.gain.setValueAtTime(vol*0.15,t);oEnv2.gain.exponentialRampToValueAtTime(0.001,t+pingDur*0.6);osc2.connect(oEnv2).connect(dest);osc2.start(t);osc2.stop(t+pingDur+0.05);return{stop(){}};}
