function generateCollisionShader(effect){const sdfCode=effect.sdfCode||EFFECT_PRESETS.sphere.sdfCode;const helperCode=effect.helperCode||'';return`
${SDF_HELPERS_WGSL}

// User helper functions
${helperCode}

// User SDF function - SAME as visual shader!
${sdfCode}

// Evaluate SDF at world position relative to particle
fn evaluateParticleSDF(
  queryPos: vec3<f32>,
  particlePos: vec3<f32>,
  particleRadius: f32,
  time: f32,
  params: vec4<f32>
) -> f32 {
  // Transform to local particle space (normalized)
  let localPos = (queryPos - particlePos) / particleRadius;
  return customSDF(localPos, time, params) * particleRadius;
}

// Get collision normal from SDF gradient
fn getCollisionNormal(
  queryPos: vec3<f32>,
  particlePos: vec3<f32>,
  particleRadius: f32,
  time: f32,
  params: vec4<f32>
) -> vec3<f32> {
  let localPos = (queryPos - particlePos) / particleRadius;
  return calcSDFNormal(localPos, time, params);
}
`;}
function validateEffect(effect){const errors=[];if(!effect.id){errors.push('Effect must have an id');}
if(!effect.name){errors.push('Effect must have a name');}
if(!effect.sdfCode){errors.push('Effect must have sdfCode');}else{if(!effect.sdfCode.includes('fn customSDF')){errors.push('sdfCode must contain "fn customSDF(p: vec3<f32>, time: f32, params: vec4<f32>) -> f32"');}}
if(effect.colorCode&&!effect.colorCode.includes('fn customColor')){errors.push('colorCode must contain "fn customColor(...) -> vec4<f32>"');}
return{valid:errors.length===0,errors};}
