// Volume: vec4(type, centerX, centerY, centerZ), vec4(sizeX, sizeY, sizeZ, 0)
// Types: 1=sphere (sizeX=radius), 2=box (size=half extents), 3=cylinder (sizeX=radius, sizeY=halfHeight)
