    @location(1) normal: vec3<f32>,
    @location(2) uv: vec2<f32>,
    @location(3) color: vec4<f32>,
    @location(4) tangent: vec3<f32>,
    @location(5) materialParams: vec4<f32>,  // x=anisotropy, y=sheenStrength, z=roughness, w=twistAngle
