  output.normalLinearDepth = vec4<f32>(primary.normal, primary.distance);
  output.albedoRoughness = vec4<f32>(base.rgb, params.x);
  output.motionMetalMaterial = vec4<f32>(0.0, 0.0, params.y, f32(primary.materialIndex));
