    var newH = centerH;
    if (neighborCount > 0.0) {
        // Transfer material out (divided among steep neighbors)
        newH -= totalTransfer / neighborCount;
    }
    
    // Also receive material from higher neighbors
    // (This is handled implicitly since we process all cells)
    
