const freshWal=new Uint8Array(WAL_HEADER_SIZE);const headerView=new DataView(freshWal.buffer);headerView.setUint32(0,WAL_MAGIC,true);headerView.setUint32(4,WAL_VERSION,true);headerView.setUint32(8,this.walLSN>>>0,true);headerView.setUint32(12,0,true);headerView.setUint32(16,checkpointLSN>>>0,true);headerView.setUint32(20,0,true);await this.backend.writeFile(WAL_FILE,freshWal);this.walCheckpointLSN=checkpointLSN;this.walDurableLSN=checkpointLSN;this.walFileSize=WAL_HEADER_SIZE;const elapsed=performance.now()-startTime;if(elapsed>100){console.log(`[WAL] Checkpoint complete in ${elapsed.toFixed(1)}ms, LSN: ${this.walLSN}`);}
