setPlayerPosition(chunkX,chunkY=0,chunkZ){this.playerChunk.x=chunkX;this.playerChunk.y=chunkY;this.playerChunk.z=chunkZ;}
_batchLog(type){this.pendingLogs[type]++;if(!this.logBatchTimer){this.logBatchTimer=setTimeout(()=>{this._flushLogs();},LOG_BATCH_FLUSH_MS);}}
_flushLogs(){this.logBatchTimer=null;if(this.verbosity===0){this.pendingLogs={loaded:0,saved:0,generated:0};return;}
const{loaded,saved,generated}=this.pendingLogs;const parts=[];if(loaded>0)parts.push(`${loaded} loaded`);if(saved>0)parts.push(`${saved} saved`);if(generated>0)parts.push(`${generated} generated`);this.pendingLogs={loaded:0,saved:0,generated:0};}
