queueModification(chunk){if(this.closing)throw worldFormatError('WORLD_STORAGE_CLOSING','Cannot queue a modification while world storage is closing');const key=chunkKey(chunk.cx??chunk.x,chunk.cy??chunk.y??0,chunk.cz??chunk.z);const chunkCopy={x:chunk.cx??chunk.x,y:chunk.cy??chunk.y??0,z:chunk.cz??chunk.z,voxels:chunk.voxels?new Uint8Array(chunk.voxels):null,entities:chunk.entities?[...chunk.entities]:[],metadata:chunk.metadata?{...chunk.metadata}:{solidCount:chunk.solidCount||0},size:chunk.size||32,};this.modificationQueue.set(key,{chunk:chunkCopy,timestamp:Date.now()});this.lastModificationTime=Date.now();this._resetIdleFlushTimer();}
