const elapsed=performance.now()-startTime;this.stats.saveTime+=elapsed;this.saving=false;if(this.verbosity>=1&&allSucceeded){console.log(`[WorldStorage] ✓ Save complete (${regionsToSave} regions in ${elapsed.toFixed(1)}ms)`);}else if(!allSucceeded){console.warn(`[WorldStorage] Save incomplete; ${this.dirtyRegions.size} region(s) remain dirty`);}
