recordVoxelChange(chunkX,chunkY,chunkZ,voxelIndex,oldValue,newValue,playerId=0){const key=chunkKey(chunkX,chunkY,chunkZ);this.historyManager.recordVoxelChange(key,voxelIndex,oldValue,newValue,playerId);}
recordEntitySpawn(chunkX,chunkY,chunkZ,entityId,entityData,playerId=0){const key=chunkKey(chunkX,chunkY,chunkZ);this.historyManager.recordEntitySpawn(key,entityId,entityData,playerId);}
