async saveAll(){for(const[key,{chunk}]of this.modificationQueue){this.saveQueue.set(key,{chunk,options:{}});}
this.modificationQueue.clear();while(this.saveQueue.size>0){const pendingBefore=this.saveQueue.size;await this._flushSaveQueue(pendingBefore,{reschedule:false});if(this.saveQueue.size>=pendingBefore)return false;}
if(!await this.saveDirtyRegions())return false;await this._saveMetadata();return true;}
setPlayerPosition(position){this.metadata.playerPosition=position;}
getPlayerPosition(){return this.metadata.playerPosition;}
updatePlayTime(deltaMs){this.metadata.playTime+=deltaMs;}
getWorldInfo(){return{name:this.worldName,seed:this.worldSeed,created:this.metadata.created,lastSaved:this.metadata.lastSaved,playTime:this.metadata.playTime,};}
static async listWorlds(){try{const db=await WorldStorage._openHandleDB();return new Promise((resolve,reject)=>{const tx=db.transaction('handles','readonly');const store=tx.objectStore('handles');const request=store.getAllKeys();request.onsuccess=()=>{db.close();resolve(request.result||[]);};request.onerror=()=>{db.close();resolve([]);};});}catch(e){console.warn('[WorldStorage] Could not list worlds:',e);return[];}}
static _openHandleDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('WorldHandles',1);request.onupgradeneeded=(e)=>{const db=e.target.result;if(!db.objectStoreNames.contains('handles')){db.createObjectStore('handles',{keyPath:'worldName'});}};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
static async storeWorldHandle(worldName,handle){try{const rootId=await WorldStorage._getOrCreateRootId(handle);const db=await WorldStorage._openHandleDB();return new Promise((resolve,reject)=>{const tx=db.transaction('handles','readwrite');const store=tx.objectStore('handles');store.put({worldName,handle,lastAccess:Date.now(),rootId:rootId||null});tx.oncomplete=()=>{db.close();console.log(`[WorldStorage] Stored handle for "${worldName}" root=${handle?.name || '?'} rootId=${rootId || 'null'}`);resolve(true);};tx.onerror=()=>{db.close();resolve(false);};});}catch(e){console.warn('[WorldStorage] Could not store handle:',e);return false;}}
