    if (chunkData.w == 0) {
        return;
    }
    
    let cx = chunkData.x;
    let cy = chunkData.y;
    let cz = chunkData.z;
    
    let dx = f32(cx - params.playerChunkX);
    let dy = f32(cy - params.playerChunkY);
    let dz = f32(cz - params.playerChunkZ);
