    let gy0 = wgBase.y + tileBase.y;
    let gz0 = wgBase.z + tileBase.z;
    let sx0 = i32(tileBase.x) + 1;
    let sy0 = i32(tileBase.y) + 1;
    let sz0 = i32(tileBase.z) + 1;
