track.addEventListener('click',(e)=>{if(!isDragging){const rect=track.getBoundingClientRect();const percentage=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));const newValue=config.min+(percentage*(config.max-config.min));updateSlider(newValue);}});thumb.addEventListener('mousedown',(e)=>{isDragging=true;thumb.style.cursor='grabbing';thumb.style.transform='translateX(-50%) scale(1.2)';e.preventDefault();});function handleMouseMove(e){if(isDragging){const rect=track.getBoundingClientRect();const percentage=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));const newValue=config.min+(percentage*(config.max-config.min));updateSlider(newValue);}}
