document.addEventListener('mousemove',handleMouseMove);document.addEventListener('mouseup',handleMouseUp);sliderElement.addEventListener('keydown',(e)=>{switch(e.key){case'ArrowLeft':case'ArrowDown':e.preventDefault();updateSlider(currentValue-config.step);break;case'ArrowRight':case'ArrowUp':e.preventDefault();updateSlider(currentValue+config.step);break;case'Home':e.preventDefault();updateSlider(config.min);break;case'End':e.preventDefault();updateSlider(config.max);break;}});sliderElement.setAttribute('tabindex','0');track.appendChild(fill);track.appendChild(thumb);sliderElement.appendChild(track);sliderElement.appendChild(valueDisplay);document.body.appendChild(sliderElement);requestAnimationFrame(()=>{sliderElement.style.opacity='1';sliderElement.style.transform='translate(-50%, -50%) scale(1)';});setTimeout(()=>{const outsideClickHandler=(e)=>{if(!sliderElement.contains(e.target)){closeSlider();document.removeEventListener('click',outsideClickHandler);}};document.addEventListener('click',outsideClickHandler);},100);const escapeHandler=(e)=>{if(e.key==='Escape'){closeSlider();document.removeEventListener('keydown',escapeHandler);}};document.addEventListener('keydown',escapeHandler);function closeSlider(){document.removeEventListener('mousemove',handleMouseMove);document.removeEventListener('mouseup',handleMouseUp);sliderElement.style.opacity='0';sliderElement.style.transform='translate(-50%, -50%) scale(0.9)';setTimeout(()=>{if(sliderElement.parentNode){sliderElement.parentNode.removeChild(sliderElement);}},200);}
