config.data.forEach(node=>{const treeNode=createTreeNode(node);treeContainer.appendChild(treeNode);});treeElement.appendChild(treeContainer);document.body.appendChild(treeElement);requestAnimationFrame(()=>{treeElement.style.opacity='1';treeElement.style.transform='translate(-50%, -50%) scale(1)';});setTimeout(()=>{const outsideClickHandler=(e)=>{if(!treeElement.contains(e.target)){closeTree();document.removeEventListener('click',outsideClickHandler);}};document.addEventListener('click',outsideClickHandler);},100);const escapeHandler=(e)=>{if(e.key==='Escape'){closeTree();document.removeEventListener('keydown',escapeHandler);}};document.addEventListener('keydown',escapeHandler);function closeTree(){treeElement.style.opacity='0';treeElement.style.transform='translate(-50%, -50%) scale(0.9)';setTimeout(()=>{if(treeElement.parentNode){treeElement.parentNode.removeChild(treeElement);}},200);}
