function getGapValue(gap){const gaps={none:'0',xs:tokens.get('spacing.xs'),sm:tokens.get('spacing.sm'),md:tokens.get('spacing.md'),lg:tokens.get('spacing.lg'),xl:tokens.get('spacing.xl'),xxxl:tokens.get('spacing.xxxl')};return gaps[gap]||gaps.md;}
